                    return r
            x, y = v.get("x"), v.get("y")
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return [int(x), int(y)]
        elif isinstance(v, (list, tuple)):
            if len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float)):
                return [int(v[0]), int(v[1])]
            for t in v:
                r = pos(t)
                if r is not None:
                    return r
        return None

    s = pos(observation.get("self_position")) or [0, 0]
    o = pos(observation.get("opponent_position")) or [W // 2, H // 2]
    obs = {tuple(p) for p in (observation.get("obstacles") or []) if pos(p) is not None}
    res = [pos(r) for r in (observation.get("resources") or [])]
    res = [p for p in res if p is not None and tuple(p) not in obs]

