            if abs(tx - o[0]) + abs(ty - o[1]) <= 1:
                v -= 2
            if v > bestv:
                bestv, best = v, [dx, dy]

    if best is None:
        cur = observation.get("scores") or [0, 0]
        lead = (cur[0] - cur[1]) if isinstance(cur, (list, tuple)) and len(cur) >= 2 else 0
        if lead < 0:
            dx, dy = step(s, o)
            dx, dy = -dx, -dy
